from research_helpers import *
a=ev('https://www.daihen.co.jp/en/products/cleanrobot/','Eleven named wafer-transfer robot model/family entries reviewed; combined AFX/W and UTX/W identifiers preserved as families, not fabricated variants.')
b=ev('https://www.daihen.co.jp/en/products/cleanrobot/index02.html','Two current wafer-aligner families explicitly identified.')
c=ev('https://www.daihen.co.jp/en/products/cleanrobot/index04.html','Eleven panel-transfer robot offerings reviewed including two engineer-to-order FOPLP models.')
d=ev('https://www.daihen-robot.com/en/products/04','Seven named robot sensor offerings reviewed; inconsistent FD-AR type labels not propagated.')
e=ev('https://www.daihen-robot.com/en/products/07','Three own-brand robot software tools and offered IsaGraphWorkbench listed; third-party software attributed as commercial partner.')
f=ev('https://www.daihen-robot.com/en/products/03','Five named robot positioner/transport families; internal exact model variants not expanded.')
products=[]
for name in 'UT-VSW3000NS UT-VDX3000NS UT-VDW3000HS UTVW-R2800H UT-VFX3000NM UT-AXW3000NS UTM-R3700F UT-AFX/W4000 UT-AFX/W3000NM UTW-REH5500 UTX/W-RF5500RW'.split():products.append(p('DAIHEN ACTRANS '+name,'Wafer-transfer robot model/family.',a,life='commercial',typ='product',sector='semiconductors',sub='semiconductor_equipment',roles=['developer','manufacturer']))
for name in ['EG-303','OFH-4100']:products.append(p('DAIHEN ACTRANS '+name,'Wafer-aligner family.',b,life='commercial',typ='product',sector='semiconductors',sub='semiconductor_equipment'))
for name in 'SPR-AD008BTN-154/035 SPR-AD008BWN-154/070 SPR-801R SPR-804R SPR-811R SPR-8565 SPR-8566 SPR-8508R SPR-8571 SPR-8572 SPR-8573'.split():products.append(p('DAIHEN '+name,'Panel-transfer robot; engineer-to-order FOPLP packaging configuration.' if 'AD008' in name else 'Flat-panel-transfer robot.',c,life='commercial',typ='product',sector='robotics',sub='industrial_robotics'))
for name in ['FD-WD','FD-AR','FD-QD','FD-QF','FD-QT','FD-QTS','2D Vision Sensor']:products.append(p('DAIHEN '+name,'Robot sensing offering.',d,life='commercial',typ='product',sector='robotics',sub='autonomy_and_components'))
for name,desc in [('FD-ST','Robot offline teaching software.'),('FD-AM','Robotic welding quality-control software.'),('FD-PM','Robot external-storage software.')]:products.append(p('DAIHEN '+name,desc,e,life='commercial',typ='product',sector='robotics',sub='autonomy_and_components'))
products.append(p('DAIHEN IsaGraphWorkbench offering','Third-party software offered for robot-system control; not attributed as original DAIHEN invention.',e,life='commercial',typ='product',sector='robotics',sub='autonomy_and_components',roles=['commercial_partner']))
for name,desc in [('1PB series','Single-axis headstock robot positioner family.'),('1PC series','Single-axis headstock robot positioner family.'),('Tilt-Rotate 2-axis positioner','Robot workpiece positioning family.'),('1SB series','Robot transport-unit family.'),('1SR series','Robot transport-unit family.')]:products.append(p('DAIHEN '+name,desc,f,life='commercial',typ='product',sector='robotics',sub='autonomy_and_components'))
co=dict(company_id='cmp_2fe2e646-d117-4d7f-9262-3b85673da2c5',products=products,evidence=[a,b,c,d,e,f],status='partial',coverage_note='71 total DAIHEN offerings: prior 31 robot/controller/package records plus 11 wafer-transfer robot families, two aligners, eleven panel-transfer robots, seven sensors, four software offerings and five positioner/transport families. Combined slash identifiers retained as families. Third-party software commercial relation distinct from developer. Partial: semiconductor RF power systems, AMRs, robot peripherals, earlier FD families, exact positioner models and energy-storage products remain. Main AMR link returned 404; no unverified model inferred.')
assert len(products)==40
(out/'batch-0378.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
